-- =====================================================================
-- Демо-спецтехника: 40 единиц для демонстрации всех типов работ
-- Добавляется в снапшоты поверх реального парка автобусов
-- Покрывает все типы работ из таблицы compatibility
-- =====================================================================

BEGIN;

-- Удаляем старые записи спецтехники (wialon_id >= 90000000) перед вставкой
-- Удаляем все старые записи из снапшотов (оставляем только нашу спецтехнику)
DELETE FROM "references".wialon_units_snapshot_1;
DELETE FROM "references".wialon_units_snapshot_2;
DELETE FROM "references".wialon_units_snapshot_3;
DELETE FROM public.vehicle_registry;




-- Обновляем vehicle_registry для новых машин
SELECT wialon_id, COALESCE(registration_plate,''), public.detect_vehicle_type(nm), nm, 'auto'
FROM "references".wialon_units_snapshot_1
WHERE wialon_id >= 90000000
ON CONFLICT (wialon_id) DO UPDATE SET
    vehicle_type = EXCLUDED.vehicle_type,
    display_name = EXCLUDED.display_name,
    updated_at   = NOW();

COMMIT;

-- Проверка
SELECT vehicle_type, COUNT(*) FROM public.vehicle_registry
WHERE wialon_id >= 90000000
GROUP BY vehicle_type ORDER BY vehicle_type;
